-- Maine, all three batches. The state had two stops.
--
-- Paul Bunyan & Babe the Blue Ox dropped: already in the index at Rumford,
-- added when the New England trip was written. Bangor's Paul Bunyan Statue
-- goes in as paul-bunyan-statue-bangor, because Atlanta, Illinois holds the
-- plain slug — there are a great many Paul Bunyans and no two of them are in
-- the same place.
--
-- Maine arrived with its own vocabulary for access, and each word said
-- something worth keeping: hike and remote-hike mean you walk, boat-access
-- means you need a boat, private-view means somebody's house, festival-only
-- means it exists for a week a year. All map onto the five states the schema
-- has, but the descriptions carry the detail.
--
-- Nineteen categories needed adding and most were singular forms of ones
-- already mapped — odd-museum against odd-museums, natural-oddity against
-- natural-oddities. The normaliser now tries the other number before giving
-- up, so neither spelling has to be listed twice again.
--
-- 129 stops, every one with a source.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('International Cryptozoology Museum', 'international-cryptozoology-museum', 'cryptids', 44.81827, -68.77495, 'Bangor', 'ME', 'The International Cryptozoology Museum moved to Bangor in 2026, bringing its collection of Bigfoot casts, cryptid artifacts, alleged evidence, pop-culture objects, and decades of cryptozoology history to a new home on Broadway. It is one of the most directly on-theme OddWay stops in the state.', 'limited', 'https://cryptozoologymuseum.com/plan-your-visit/', 'https://cryptozoologymuseum.com/', 'America/New_York', now()),
  ('Stephen King’s Former House', 'stephen-kings-former-house', 'roadside-oddities', 44.80231, -68.78504, 'Bangor', 'ME', 'Stephen King’s famous red Victorian mansion and its spider-and-bat iron gate are among Bangor’s most recognizable landmarks. King no longer lives here; this is a private property stop, so view it only from the public sidewalk or street.', 'private', 'https://www.atlasobscura.com/places/stephen-kings-house', null, 'America/New_York', now()),
  ('Thomas Hill Standpipe', 'thomas-hill-standpipe', 'weird-history', 44.80741, -68.7825, 'Bangor', 'ME', 'Built in 1897, this enormous wooden water tank is enclosed by a shingled structure that looks more like an oversized lighthouse than municipal infrastructure. Its exterior is easy to see, while interior access is limited to occasional public open houses.', 'limited', 'https://fotospot.com/attractions/maine/thomas-hill-standpipe', null, 'America/New_York', now()),
  ('Paul Bunyan Statue', 'paul-bunyan-statue-bangor', 'roadside-oddities', 44.78795, -68.77828, 'Bangor', 'ME', 'Bangor’s 31-foot Paul Bunyan has stood near Main Street since 1959 and represents the city’s claim to the legendary lumberjack. The giant fiberglass figure also fits neatly into Bangor’s larger Stephen King and folklore identity.', 'open', 'https://www.maine.gov/sos/maineatlas/explore-the-atlas/paul-bunyan-statue', null, 'America/New_York', now()),
  ('Mount Hope Cemetery', 'mount-hope-cemetery', 'weird-history', 44.82442, -68.71984, 'Bangor', 'ME', 'One of the country’s oldest garden cemeteries, Mount Hope is full of elaborate monuments, wooded lanes, and centuries of Bangor history. Horror fans also know it as a filming location used in Stephen King’s Pet Sematary.', 'limited', 'https://www.atlasobscura.com/places/mount-hope-cemetery-bangor', null, 'America/New_York', now()),
  ('Colonel Buck’s Cursed Tomb', 'colonel-bucks-cursed-tomb', 'folklore', 44.57119, -68.78435, 'Bucksport', 'ME', 'A strange boot- or foot-shaped stain marks the monument of Colonel Jonathan Buck, the founder for whom Bucksport was named. Local legend claims the mark is tied to a curse involving an executed witch, although the story is folklore rather than documented history.', 'limited', 'https://www.roadsideamerica.com/story/6159', null, 'America/New_York', now()),
  ('Fort Knox State Historic Site', 'fort-knox-state-historic-site', 'weird-history', 44.56615, -68.80243, 'Prospect', 'ME', 'This massive granite fortification was built in the 1800s to guard the Penobscot River and contains tunnels, stairways, cannon positions, and dark interior passages. The preserved fort is open to visitors seasonally, with some access varying by time of year.', 'limited', 'https://www.maine.gov/fortknox', null, 'America/New_York', now()),
  ('Penobscot Narrows Bridge Observatory', 'penobscot-narrows-bridge-observatory', 'roadside-oddities', 44.56053, -68.80378, 'Prospect', 'ME', 'An elevator inside one of the Penobscot Narrows Bridge towers carries visitors to an observation room about 420 feet above the river. The enclosed observatory offers a 360-degree view and is accessed through the Fort Knox historic-site entrance.', 'limited', 'https://www.maine.gov/dot/pnbo', null, 'America/New_York', now()),
  ('Perry’s Nut House', 'perrys-nut-house', 'roadside-oddities', 44.43323, -68.99848, 'Belfast', 'ME', 'Perry’s Nut House is a surviving piece of old-school Maine roadside culture, historically famous for taxidermy, curiosities, oversized objects, souvenirs, and odd displays. The revived shop continues the name and keeps the strange roadside-stop tradition alive.', 'limited', 'https://www.maine.gov/sos/maineatlas/explore-the-atlas/perrys-nut-house', null, 'America/New_York', now()),
  ('Skowhegan Indian — Bernard Langlais Sculpture', 'skowhegan-indian-bernard-langlais-sculpture', 'roadside-oddities', 44.76777, -69.7198, 'Skowhegan', 'ME', 'Bernard Langlais created this approximately 62-foot wooden sculpture for Maine’s 1969 bicentennial, and it became one of the state’s most recognizable roadside giants. The weather-damaged sculpture is undergoing an active preservation effort in 2026, so its appearance may change as work continues. Preservation update: https://www.wagmtv.com/2026/08/31/new-local-group-steps-save-restore-famous-62-foot-skowhegan-indian-sculpture/', 'roadside', 'https://www.roadsideamerica.com/story/6162', null, 'America/New_York', now()),
  ('B-52 Crash Site Memorial — Elephant Mountain', 'b-52-crash-site-memorial-elephant-mountain', 'weird-history', 45.52778, -69.43472, 'Greenville', 'ME', 'Wreckage from a U.S. Air Force B-52 that crashed on Elephant Mountain during a 1963 training mission remains scattered in the woods near a memorial. Seven crew members died and two survived; visitors should treat the site as both a historical location and a memorial.', 'limited', 'https://www.visitmaine.net/b52-crash-site-maine/', null, 'America/New_York', now()),
  ('Flying Moose Statue', 'flying-moose-statue', 'folklore', 45.66789, -69.74436, 'Rockwood', 'ME', 'A carved moose with large wings stands beside the road north of Rockwood, accompanied by a sign recounting a locally attributed Abenaki flying-moose legend. It is best treated as a roadside viewing stop without entering the nearby private property.', 'roadside', 'https://www.roadsideamerica.com/tip/638', null, 'America/New_York', now()),
  ('Wilhelm Reich Museum at Orgonon', 'wilhelm-reich-museum-at-orgonon', 'museums', 44.98442, -70.71083, 'Rangeley', 'ME', 'This former research estate preserves the life and work of controversial psychoanalyst Wilhelm Reich, including his theories about an energy he called “orgone.” The property is associated with Reich’s unusual experiments, cloudbuster devices, laboratory work, and later conflict with federal authorities.', 'limited', 'https://www.atlasobscura.com/places/wilhelm-reich-museum', null, 'America/New_York', now()),
  ('Maine Mineral & Gem Museum', 'maine-mineral-gem-museum', 'museums', 44.4077, -70.7887, 'Bethel', 'ME', 'This museum combines Maine mining history with an unusually strong meteorite collection, including material from the Moon and Mars. Its mix of gemstones, space rocks, and geological specimens makes it much stranger than a standard local-history museum.', 'limited', 'https://mainemineralmuseum.org/visit/', null, 'America/New_York', now()),
  ('World’s Largest Telephone', 'worlds-largest-telephone', 'roadside-oddities', 44.3785, -70.64621, 'Bryant Pond', 'ME', 'A roughly 14-foot-tall telephone commemorates Bryant Pond’s place in telecommunications history as the home of the last hand-cranked telephone exchange in the United States. The giant phone stands as a roadside monument to the town’s unusually late survival of operator-connected service.', 'roadside', 'https://www.maine.gov/sos/maineatlas/explore-the-atlas/worlds-largest-telephone', null, 'America/New_York', now()),
  ('Duck of Justice — Bangor Police Museum', 'duck-of-justice-bangor-police-museum', 'museums', 44.79717, -68.77299, 'Bangor', 'ME', 'The unlikely star of the Bangor Police Museum is the Duck of Justice, a taxidermied wood duck rescued from a trash bin and transformed into the department’s internet-famous mascot. The small museum is inside the police department and is currently viewed by appointment.', 'limited', 'https://www.bangormaine.gov/389/Police-Department-Museum', null, 'America/New_York', now()),
  ('World Traveler Signpost', 'world-traveler-signpost', 'roadside-oddities', 44.24434, -70.78508, 'Lynchville', 'ME', 'At a rural Maine crossroads, a cluster of signs points toward nearby towns with names borrowed from places around the world, including Norway, Paris, Denmark, Sweden, and Mexico. The result looks like an international directional sign dropped into the Maine woods.', 'roadside', 'https://www.maine.gov/sos/maineatlas/explore-the-atlas/world-traveler-signpost', null, 'America/New_York', now()),
  ('Devil’s Footprint', 'devils-footprint', 'folklore', 44.3635, -69.8693, 'Manchester', 'ME', 'A large foot-shaped depression in a boulder beside the North Manchester Meeting House has long been explained through local stories involving the Devil. The stone sits near the cemetery and can be viewed without wandering onto unrelated private property.', 'roadside', 'https://www.roadsideamerica.com/tip/67410', null, 'America/New_York', now()),
  ('Desert of Maine', 'desert-of-maine', 'roadside-oddities', 43.85921, -70.15544, 'Freeport', 'ME', 'A broad expanse of exposed glacial sand sits unexpectedly among the forests of Freeport, creating one of Maine’s strangest landscapes. Despite the name, it is not a true climatic desert; the unusual sand deposit became a long-running roadside attraction.', 'limited', 'https://desertofmaine.com/visit', null, 'America/New_York', now()),
  ('Giant L.L.Bean Boot', 'giant-llbean-boot', 'roadside-oddities', 43.85788, -70.10389, 'Freeport', 'ME', 'A huge version of L.L.Bean’s signature Maine Hunting Shoe stands outside the company’s flagship complex in Freeport. It is a simple but iconic oversized-object stop that works well as a quick route detour.', 'roadside', 'https://fotospot.com/attractions/maine/giant-ll-bean-boot', null, 'America/New_York', now()),
  ('Eartha — Giant Rotating Globe', 'eartha-giant-rotating-globe', 'museums', 43.80794, -70.16399, 'Yarmouth', 'ME', 'Eartha is an enormous rotating globe installed inside the former DeLorme headquarters, now associated with Garmin. The three-story sphere turns slowly inside a glass atrium and can also be seen from outside the building.', 'limited', 'https://www.atlasobscura.com/places/eartha-delorme-headquarters', null, 'America/New_York', now()),
  ('Umbrella Cover Museum', 'umbrella-cover-museum', 'museums', 43.6561, -70.198, 'Peaks Island, Portland', 'ME', 'This tiny museum is devoted entirely to umbrella sleeves and covers collected from around the world. Reaching it requires a ferry ride to Peaks Island, and its operating schedule is seasonal.', 'limited', 'https://www.umbrellacovermuseum.org/', null, 'America/New_York', now()),
  ('Battery Steele', 'battery-steele', 'weird-history', 43.6587, -70.1798, 'Peaks Island, Portland', 'ME', 'Built during World War II, Battery Steele is a long concrete coastal-defense battery now covered in graffiti and surrounded by island trails. Visitors can walk through portions of its dark, bunker-like corridors, making it one of the more atmospheric ruins near Portland.', 'open', 'https://www.atlasobscura.com/places/battery-steele', null, 'America/New_York', now()),
  ('Berlin Wall Slabs', 'berlin-wall-slabs', 'weird-history', 43.65557, -70.25228, 'Portland', 'ME', 'Several sections of the Berlin Wall stand outdoors near Portland’s waterfront, an unexpected fragment of Cold War history far from Germany. The slabs are publicly viewable along the Commercial Street/Long Wharf area.', 'open', 'https://www.waymarking.com/waymarks/WM10A1N_Berlin_Wall_Slabs_Portland_ME', null, 'America/New_York', now()),
  ('Fort Gorges', 'fort-gorges', 'weird-history', 43.66312, -70.22164, 'Portland', 'ME', 'This granite Civil War-era fort occupies its own island in Portland Harbor and resembles a smaller coastal cousin of Fort Sumter. There is no road connection or regular public ferry, so visiting requires appropriate boat access and safe conditions.', 'limited', 'https://www.atlasobscura.com/places/fort-gorges', null, 'America/New_York', now()),
  ('Lenny the Chocolate Moose', 'lenny-the-chocolate-moose', 'roadside-oddities', 43.58673, -70.35322, 'Scarborough', 'ME', 'Lenny is a life-size moose made from about 1,700 pounds of milk chocolate and displayed inside Len Libby Candies. He is joined by other chocolate woodland figures in one of Maine’s strangest edible-looking roadside displays.', 'limited', 'https://www.atlasobscura.com/places/lenny-the-chocolate-moose', null, 'America/New_York', now()),
  ('Old Bet Elephant Memorial', 'old-bet-elephant-memorial', 'weird-history', 43.45722, -70.71944, 'Alfred', 'ME', 'A roadside marker commemorates the place where the traveling circus elephant Old Bet was reportedly shot and killed in 1816. The bizarre episode became part of early American circus history, and a granite monument now marks the location.', 'roadside', 'https://www.roadsideamerica.com/story/53175', null, 'America/New_York', now()),
  ('Wedding Cake House', 'wedding-cake-house', 'roadside-oddities', 43.38145, -70.5172, 'Kennebunk', 'ME', 'Elaborate white Gothic woodwork covers this 19th-century home so densely that it resembles layers of decorative cake icing. The house is privately owned, so this is a look-from-the-public-road stop only.', 'private', 'https://www.atlasobscura.com/places/the-wedding-cake-house', null, 'America/New_York', now()),
  ('Seashore Trolley Museum', 'seashore-trolley-museum', 'museums', 43.407, -70.4896, 'Kennebunkport', 'ME', 'The Seashore Trolley Museum preserves a huge collection of historic streetcars, buses, rapid-transit vehicles, and other public transportation equipment. Seasonal operating days can include rides aboard restored railway vehicles.', 'limited', 'https://trolleymuseum.org/', null, 'America/New_York', now()),
  ('Maine Classic Car Museum', 'maine-classic-car-museum', 'museums', 43.45171, -70.4973, 'Arundel', 'ME', 'This museum displays an eclectic collection of restored automobiles, motorcycles, automobilia, and unusual vehicles rather than focusing on a single make or era. Its highly visual collection makes it an easy OddWay stop even for travelers who are not dedicated car enthusiasts.', 'limited', 'https://www.mainecarmuseum.com/', null, 'America/New_York', now()),
  ('Captain Brown — Giant Old Salt Fisherman', 'captain-brown-giant-old-salt-fisherman', 'roadside-oddities', 43.845, -69.626, 'Boothbay Harbor', 'ME', 'A roughly 25-foot fiberglass fisherman has watched over Brown’s Wharf since the late 1960s. The oversized old salt, complete with rain gear and pipe, is one of the classic giant figures of Maine roadside culture.', 'roadside', 'https://www.roadsideamerica.com/tip/1955', null, 'America/New_York', now()),
  ('Guardians of the Seeds Trolls', 'guardians-of-the-seeds-trolls', 'roadside-oddities', 43.8736, -69.66072, 'Boothbay', 'ME', 'Five enormous wooden trolls created by artist Thomas Dambo are hidden along trails at Coastal Maine Botanical Gardens. The sculptures form the “Guardians of the Seeds” installation and turn a garden hike into a giant-creature scavenger hunt.', 'limited', 'https://www.mainegardens.org/classes-and-events/hike-the-trolls/', null, 'America/New_York', now()),
  ('Opera House at Boothbay Harbor', 'opera-house-at-boothbay-harbor', 'haunted', 43.85433, -69.62652, 'Boothbay Harbor', 'ME', 'The 1894 Opera House remains an active performance venue, but it also carries a long-running reputation for unexplained activity. Local ghost lore includes stories about sounds, movement, and a purported presence sometimes nicknamed “Fingers”; these are legends, not verified paranormal claims.', 'limited', 'https://boothbayoperahouse.com/', null, 'America/New_York', now()),
  ('Monster of Unfathomable Pedigree', 'monster-of-unfathomable-pedigree', 'roadside-oddities', 43.90695, -69.82946, 'Bath', 'ME', 'This strange red creature is assembled from salvaged metal and found objects, producing something between a dragon, mechanical beast, and junkyard monster. It sits where passing travelers can get a look without needing a full museum stop.', 'roadside', 'https://www.roadsideamerica.com/tip/25676', null, 'America/New_York', now()),
  ('Larry the Lobster at Taste of Maine', 'larry-the-lobster-at-taste-of-maine', 'roadside-oddities', 43.9208, -69.79909, 'Woolwich', 'ME', 'A gigantic inflatable lobster named Larry sprawls across the roof of Taste of Maine Restaurant. The oversized crustacean has become a highly visible Route 1 landmark and one of the state’s easiest drive-by oddities.', 'roadside', 'https://tasteofmaine.com/', null, 'America/New_York', now()),
  ('Andre the Seal Statue', 'andre-the-seal-statue', 'weird-history', 44.18617, -69.07379, 'Rockport', 'ME', 'A life-size granite statue on the Rockport waterfront honors Andre, the harbor seal who became a local celebrity through his relationship with harbor master Harry Goodridge. Andre’s true story inspired books and films and remains an unusually Maine piece of animal history.', 'open', 'https://www.roadsideamerica.com/story/3632', null, 'America/New_York', now()),
  ('Captain Hanson Gregory Doughnut-Hole Monument', 'captain-hanson-gregory-doughnut-hole-monument', 'weird-history', 44.13407, -69.10012, 'Rockport', 'ME', 'Rockport honors sea captain Hanson Gregory, who is locally credited with inventing the hole in the center of the doughnut in 1847. A small monument marks the story, turning a piece of disputed food history into a routeable roadside stop.', 'roadside', 'https://www.rockportdonutfestival.com/history-of-the-donut', null, 'America/New_York', now()),
  ('Langlais Art Preserve', 'langlais-art-preserve', 'roadside-oddities', 44.04165, -69.21083, 'Cushing', 'ME', 'The former home and studio property of Maine sculptor Bernard Langlais is filled with his large, rough-hewn wooden and outdoor artworks. Visitors can walk through an unusual landscape where the art, workshop, fields, and forest all blend together.', 'open', 'https://www.langlaisartpreserve.org/', null, 'America/New_York', now()),
  ('Center of the Universe Monument', 'center-of-the-universe-monument', 'roadside-oddities', 44.01262, -69.19795, 'Saint George', 'ME', 'A roughly 16-foot granite monument topped by a monkey blowing a horn stands on private property and announces this patch of Maine as the “Center of the Universe.” It is an eccentric roadside-art stop; view it from the public road and do not enter the property.', 'private', 'https://www.roadsideamerica.com/story/70879', null, 'America/New_York', now()),
  ('Big Camera Obscura', 'big-camera-obscura', 'museums', 44.45966, -68.92489, 'Searsport', 'ME', 'A room-size camera obscura on the Penobscot Marine Museum campus is built to resemble an old box camera. Visitors can step inside and see a live, inverted image of the outside world projected through a small opening onto the interior surface. Museum: https://penobscotmarinemuseum.org/', 'limited', 'https://www.roadsideamerica.com/tip/92146', null, 'America/New_York', now()),
  ('Owls Head Transportation Museum', 'owls-head-transportation-museum', 'museums', 44.06617, -69.10127, 'Owls Head', 'ME', 'This working transportation museum preserves early aircraft, automobiles, motorcycles, engines, and other machines, with many exhibits maintained in operating condition. Demonstrations and special events can make the collection feel more like a living mechanical time capsule than a static museum.', 'limited', 'https://www.atlasobscura.com/places/owls-head-transportation-museum', 'https://owlshead.org/', 'America/New_York', now()),
  ('Nervous Nellie’s — Nellieville Sculpture Village', 'nervous-nellies-nellieville-sculpture-village', 'roadside-oddities', 44.20433, -68.58275, 'Deer Isle', 'ME', 'Behind a jam and jelly business is an sprawling handmade village of sculptures, buildings, figures, vehicles, creatures, and found-object scenes known as Nellieville. The dense folk-art environment is strange enough to be a destination on its own.', 'limited', 'https://www.nervousnellies.com/', null, 'America/New_York', now()),
  ('Nerida the Mermaid', 'nerida-the-mermaid', 'roadside-oddities', 44.90471, -66.98408, 'Eastport', 'ME', 'Nerida is a bronze mermaid sculpture installed on the Eastport waterfront in 2015. The figure ties the city’s working waterfront to maritime myth and makes an easy stop while exploring the eastern edge of Maine.', 'open', 'https://www.roadsideamerica.com/tip/82628', null, 'America/New_York', now()),
  ('Bear Head Rock', 'bear-head-rock', 'roadside-oddities', 44.90934, -66.98482, 'Eastport', 'ME', 'A cliff and rock profile across the water resembles the head of a bear when viewed from the right angle. This coordinate is a practical public viewing area on the Eastport waterfront rather than a claim that the pin sits directly on the rock formation itself.', 'open', 'https://www.roadsideamerica.com/tip/44869', null, 'America/New_York', now()),
  ('Reversing Falls Park', 'reversing-falls-park', 'roadside-oddities', 44.8917, -67.1272, 'Pembroke', 'ME', 'Powerful tides force water through a narrow channel here, creating standing waves, whirlpools, and rapids that reverse direction as the tide changes. It is a dramatic natural oddity best treated as a viewing stop rather than a swimming location.', 'open', 'https://www.newenglandswimmingholes.com/maine/waterfalls/pembroke-reversing-falls', null, 'America/New_York', now()),
  ('West Quoddy Head Light — Easternmost Point', 'west-quoddy-head-light-easternmost-point', 'roadside-oddities', 44.81511, -66.95047, 'Lubec', 'ME', 'The red-and-white striped West Quoddy Head Light stands beside the easternmost point of the contiguous United States. The lighthouse, cliffs, trails, and international views make the geographic superlative worth a stop even apart from the lighthouse itself.', 'limited', 'https://www.roadsideamerica.com/tip/44921', null, 'America/New_York', now()),
  ('Wild Blueberry Land', 'wild-blueberry-land', 'roadside-oddities', 44.64847, -67.70708, 'Columbia Falls', 'ME', 'A giant blueberry-shaped building rises beside U.S. Route 1 in Maine’s major wild-blueberry region. The seasonal attraction sells blueberry products and leans fully into its oversized-fruit roadside identity.', 'limited', 'https://www.wildblueberryland.com/contact/', null, 'America/New_York', now()),
  ('America’s First Mile', 'americas-first-mile', 'roadside-oddities', 47.24845, -68.60232, 'Fort Kent', 'ME', 'A monument in Fort Kent marks the northern beginning of U.S. Route 1, the highway that runs from northern Maine to Key West, Florida. It is a clean geographic bookend stop for anyone traveling the far northern reaches of the state.', 'roadside', 'https://www.atlasobscura.com/places/americas-first-mile', null, 'America/New_York', now()),
  ('Maine Solar System Model — The Sun', 'maine-solar-system-model-the-sun', 'museums', 46.67222, -68.01717, 'Presque Isle', 'ME', 'The Sun inside Folsom Hall at the University of Maine at Presque Isle anchors a huge scale model of the solar system whose planetary installations stretch along roads through Aroostook County. Travelers can turn the model into its own multi-stop OddWay route.', 'limited', 'https://www.mainesolarsystem.com/destinations/the-sun/', null, 'America/New_York', now()),
  ('Telephone Museum', 'telephone-museum', 'museums', 44.63743, -68.56956, 'Ellsworth', 'ME', 'This hands-on museum preserves working switchboards, telephone exchanges, switching systems, and equipment spanning generations of communication technology. Its limited seasonal schedule and appointment options make it a check-ahead stop rather than a spontaneous year-round visit.', 'limited', 'https://thetelephonemuseum.org/plan-your-visit/', 'https://thetelephonemuseum.org/', 'America/New_York', now()),
  ('Wiggly Bridge', 'wiggly-bridge', 'roadside-oddities', 43.13645, -70.64768, 'York', 'ME', 'This tiny suspension footbridge stretches about 75 feet across a tidal inlet and noticeably bounces and sways underfoot. It is often promoted as one of the smallest suspension bridges in the world and connects into the Steedman Woods trail system.', 'open', 'https://www.atlasobscura.com/places/wiggly-bridge', null, 'America/New_York', now()),
  ('York Witch Grave — Mary Nasson', 'york-witch-grave-mary-nasson', 'folklore', 43.14388, -70.65244, 'York', 'ME', 'Mary Nasson’s 1774 grave is covered by a large stone slab, which later folklore claimed was placed there to keep a witch from rising from the dead. There is no evidence Nasson was a witch; the unusually protected grave itself is real and the legend has persisted for generations.', 'open', 'https://www.atlasobscura.com/places/york-witch-grave', null, 'America/New_York', now()),
  ('Freeport McDonald’s — The Gore House', 'freeport-mcdonalds-the-gore-house', 'roadside-oddities', 43.86032, -70.10167, 'Freeport', 'ME', 'Instead of a standard fast-food building, this McDonald’s occupies the historic mid-1800s Gore House near downtown Freeport. Local design restrictions helped preserve the mansion-like exterior, producing one of the chain’s strangest-looking locations.', 'open', 'https://www.atlasobscura.com/places/mcdonalds-freeport-mansion', null, 'America/New_York', now()),
  ('Boon Island Light', 'boon-island-light', 'weird-history', 43.12116, -70.47597, 'York', 'ME', 'New England’s tallest lighthouse stands on an isolated rocky island several miles off York. Boon Island also carries grim maritime history, including an infamous 18th-century shipwreck whose stranded survivors were later associated with accounts of cannibalism.', 'roadside', 'https://www.atlasobscura.com/places/boon-island-light', null, 'America/New_York', now()),
  ('Wire Bridge', 'wire-bridge', 'roadside-oddities', 44.92526, -70.02246, 'New Portland', 'ME', 'This rural bridge combines a wooden deck and towers with an unusual wire-cable suspension system dating to the 1800s. It is commonly described as the last surviving bridge of its particular construction type in Maine.', 'open', 'https://www.atlasobscura.com/places/wire-bridge', null, 'America/New_York', now()),
  ('Bubble Rock', 'bubble-rock', 'roadside-oddities', 44.33856, -68.27334, 'Mount Desert', 'ME', 'A giant glacial boulder appears to balance precariously near the edge of South Bubble Mountain in Acadia National Park. The rock was carried and deposited by ancient ice, leaving it looking as though a small push could send it over the cliff.', 'limited', 'https://www.atlasobscura.com/places/bubble-rock', null, 'America/New_York', now()),
  ('Old Sow Whirlpool', 'old-sow-whirlpool', 'roadside-oddities', 44.92375, -66.98714, 'Eastport', 'ME', 'Powerful tides in the waters between Eastport and Deer Island create Old Sow, generally regarded as the largest tidal whirlpool in the Western Hemisphere. It can sometimes be seen from shore, but boat tours provide closer views when tides and conditions cooperate.', 'limited', 'https://www.atlasobscura.com/places/old-sow-whirlpool', null, 'America/New_York', now()),
  ('Finn’s Irish Pub — Historic Dining Car', 'finns-irish-pub-historic-dining-car', 'roadside-oddities', 44.54208, -68.42327, 'Ellsworth', 'ME', 'Hidden inside Finn’s is an original 1930s Jerry O’Mahony dining car, complete with its compact metal structure, counter, stools, and distinctive interior details. The modern restaurant was effectively built around the old diner, leaving a historic structure embedded inside another building.', 'open', 'https://www.atlasobscura.com/places/finns-irish-pub-jerry-omahony-dining-car', 'https://www.finnsirishpub.com/', 'America/New_York', now()),
  ('Gulf Hagas', 'gulf-hagas', 'roadside-oddities', 45.49628, -69.35773, 'Bowdoin College Grant East Township', 'ME', 'Nicknamed the “Grand Canyon of Maine,” Gulf Hagas is a remote slate gorge filled with waterfalls, narrow rock walls, old-growth forest, and dramatic drops along the West Branch of the Pleasant River. Reaching the best features requires a substantial wilderness hike with no reliable cell service.', 'limited', 'https://www.atlasobscura.com/places/maine-gulf-hagas', null, 'America/New_York', now()),
  ('Maine State Prison Showroom', 'maine-state-prison-showroom', 'roadside-oddities', 44.07756, -69.1915, 'Thomaston', 'ME', 'This unusual state-run showroom sells furniture, carved objects, toys, artwork, and other goods made by incarcerated people in Maine’s correctional system. The tradition dates back generations and makes the store far stranger than a typical roadside craft shop.', 'limited', 'https://www.atlasobscura.com/places/maine-state-prison-showroom', null, 'America/New_York', now()),
  ('Smuttynose Island', 'smuttynose-island', 'weird-history', 42.98242, -70.60606, 'Kittery', 'ME', 'This small Isles of Shoals island became notorious after the brutal 1873 murders of two women living there, a crime that inspired books, poems, and later retellings. The island is privately owned but traditionally allows respectful daylight visitors who arrive by their own boat and follow posted rules.', 'limited', 'https://www.atlasobscura.com/places/smutttynose-island', null, 'America/New_York', now()),
  ('Goddard Mansion Ruins', 'goddard-mansion-ruins', 'weird-history', 43.62649, -70.21419, 'Cape Elizabeth', 'ME', 'The stone shell of an elaborate 19th-century mansion stands inside Fort Williams Park near Portland Head Light. After decades of abandonment and deterioration, only the atmospheric exterior walls remain and the interior is fenced off.', 'open', 'https://www.atlasobscura.com/places/goddard-mansion', null, 'America/New_York', now()),
  ('Gnome Village', 'gnome-village', 'folklore', 44.95643, -70.5659, 'Rangeley', 'ME', 'Tiny houses and more than twenty gnome figures are scattered through the woods along trails at the Rangeley Lakes Trails Center. The handmade village turns a normal forest walk into a small-scale folklore scavenger hunt.', 'limited', 'https://www.atlasobscura.com/places/gnome-village-maine', null, 'America/New_York', now()),
  ('Portland Observatory', 'portland-observatory', 'weird-history', 43.66537, -70.24824, 'Portland', 'ME', 'Built in 1807, this octagonal wooden tower allowed signalmen to identify incoming ships before they reached Portland Harbor. It survives as the only known remaining historic maritime signal tower of its type in the United States.', 'limited', 'https://www.atlasobscura.com/places/the-portland-observatory', null, 'America/New_York', now()),
  ('Bartlettyarns Mill — Graveyard Shift Filming Location', 'bartlettyarns-mill-graveyard-shift-filming-location', 'weird-history', 44.9712, -69.54672, 'Harmony', 'ME', 'This working woolen mill supplied the exterior for the sinister textile mill in the 1990 Stephen King adaptation Graveyard Shift. It remains an active property, making this primarily a respectful exterior-viewing stop from public areas.', 'private', 'https://www.atlasobscura.com/places/bartlettyarns-mill', null, 'America/New_York', now()),
  ('Kenneth E. Stoddard Shell Museum', 'kenneth-e-stoddard-shell-museum', 'museums', 43.90734, -69.6166, 'Boothbay', 'ME', 'Thousands of seashells from around the world fill a covered-bridge-style structure at the Dolphin Mini Golf property. The dense collection ranges from familiar Maine shells to exotic specimens and is generally tied to the property’s seasonal schedule.', 'limited', 'https://www.atlasobscura.com/places/kenneth-e-stoddard-shell-museum', null, 'America/New_York', now()),
  ('Moxie Bottle House', 'moxie-bottle-house', 'roadside-oddities', 44.21427, -69.28451, 'Union', 'ME', 'A roughly 32-foot-tall wooden bottle shaped like Maine’s famously divisive Moxie soda stands at the Union Fairgrounds. The structure was originally created as a promotional building for the 1906 New England Food Fair before eventually being preserved in Maine.', 'limited', 'https://www.atlasobscura.com/places/moxie-bottle-house', null, 'America/New_York', now()),
  ('Eagle Lake Tramway and Abandoned Locomotives', 'eagle-lake-tramway-and-abandoned-locomotives', 'weird-history', 46.28611, -69.34837, 'T7 R13 WELS', 'ME', 'Deep in the North Maine Woods sit two abandoned steam locomotives and remnants of an elaborate tramway and railroad system once used to move timber between watersheds. Reaching them is a serious backcountry trip involving remote roads, trails, and careful trip planning.', 'limited', 'https://www.atlasobscura.com/places/eagle-lake-tramway', null, 'America/New_York', now()),
  ('Maine Narrow Gauge Railroad Co. & Museum', 'maine-narrow-gauge-railroad-co-museum', 'museums', 43.66042, -70.24663, 'Portland', 'ME', 'Historic two-foot-gauge railway equipment still operates along Portland’s waterfront, preserving a form of railroading once unusually common in Maine. The museum runs scheduled passenger trips in restored equipment rather than displaying the collection only as static artifacts.', 'limited', 'https://mainenarrowgauge.org/', null, 'America/New_York', now()),
  ('The Old Man of Shore Road', 'the-old-man-of-shore-road', 'roadside-oddities', 43.61389, -70.21403, 'Cape Elizabeth', 'ME', 'A coastal rock formation creates the profile of an old man’s face when seen from the correct angle along Shore Road. The naturally occurring silhouette has been compared to New Hampshire’s lost Old Man of the Mountain, though it is much easier to miss.', 'roadside', 'https://www.atlasobscura.com/places/the-old-man-of-shore-road', null, 'America/New_York', now()),
  ('Oldest 45th Parallel Marker in the U.S.', 'oldest-45th-parallel-marker-in-the-us', 'roadside-oddities', 44.99961, -67.08866, 'Perry', 'ME', 'An old granite marker beside the road commemorates the halfway point between the Equator and North Pole. Modern surveying places the exact 45th parallel a short distance away, making the historic marker both a geographic landmark and a surveying curiosity.', 'roadside', 'https://www.atlasobscura.com/places/the-oldest-45th-parallel-marker-in-the-us-perry-maine', null, 'America/New_York', now()),
  ('Mount Desert Spring Blues Brothers', 'mount-desert-spring-blues-brothers', 'roadside-oddities', 44.28867, -68.33049, 'Southwest Harbor', 'ME', 'Life-size figures of Jake and Elwood Blues stand unexpectedly outside a water-bottling facility on Mount Desert Island. The sunglasses, suits, and deadpan poses make the pair an easy-to-spot piece of roadside pop-culture weirdness.', 'roadside', 'https://www.atlasobscura.com/places/blues-brothers', null, 'America/New_York', now()),
  ('Paul Bunyan’s Severed Head', 'paul-bunyans-severed-head', 'roadside-oddities', 43.15635, -70.7371, 'York', 'ME', 'An enormous fiberglass Paul Bunyan head appears among the trees near the York River with the rest of the legendary lumberjack nowhere in sight. The head is associated with private land, so it should be viewed only from legitimate public access without entering the property.', 'private', 'https://www.atlasobscura.com/places/paul-bunyans-severed-head', null, 'America/New_York', now()),
  ('Maine Coast Sardine History Museum', 'maine-coast-sardine-history-museum', 'museums', 44.54029, -67.58804, 'Jonesport', 'ME', 'This small Downeast museum preserves the vanished world of Maine’s sardine canneries through old tins, labels, photographs, machinery, packing tables, workers’ tools, and other industrial artifacts. One especially personal display preserves scissors once used by individual cannery workers.', 'limited', 'https://www.downeastfisheriestrail.org/sites/maine-coast-sardine-history-museum/', 'https://mainesardinemuseum.tripod.com/', 'America/New_York', now()),
  ('L.C. Bates Museum', 'lc-bates-museum', 'museums', 44.66274, -69.62694, 'Hinckley', 'ME', 'The L.C. Bates feels like an old-fashioned cabinet of curiosities preserved inside a museum, with historic taxidermy, minerals, fossils, cultural artifacts, dioramas, and unusual specimens. Among its stranger holdings are a marlin associated with Ernest Hemingway and a piece of early transatlantic cable.', 'limited', 'https://www.gwh.org/programs/lc-bates-museum/', null, 'America/New_York', now()),
  ('Peary-MacMillan Arctic Museum', 'peary-macmillan-arctic-museum', 'museums', 43.90777, -69.9599, 'Brunswick', 'ME', 'Bowdoin College’s Arctic museum preserves artifacts, photographs, equipment, and records connected with Arctic exploration and northern cultures. Its collections are closely tied to explorers Robert E. Peary and Donald B. MacMillan, both Bowdoin graduates.', 'limited', 'https://www.atlasobscura.com/places/peary-macmillan-arctic-museum', null, 'America/New_York', now()),
  ('Northeast Historic Film at the Alamo Theatre', 'northeast-historic-film-at-the-alamo-theatre', 'weird-history', 44.57225, -68.79543, 'Bucksport', 'ME', 'A restored 1916 cinema houses Northeast Historic Film, an archive dedicated to preserving moving images from northern New England. The collection includes home movies, local television, industrial films, advertisements, and other footage that might otherwise have disappeared.', 'limited', 'https://www.atlasobscura.com/places/northeast-historic-film', null, 'America/New_York', now()),
  ('Maine State Building', 'maine-state-building', 'roadside-oddities', 44.0273, -70.36134, 'Poland', 'ME', 'This elaborate building was Maine’s pavilion at the 1893 World’s Columbian Exposition in Chicago. After the fair, it was dismantled, transported back to Maine by rail, and reconstructed at Poland Spring, where the former world’s-fair building still survives.', 'limited', 'https://www.atlasobscura.com/places/maine-state-building', null, 'America/New_York', now()),
  ('Thompson Ice House Harvesting Museum', 'thompson-ice-house-harvesting-museum', 'museums', 43.879, -69.5603, 'South Bristol', 'ME', 'This preserved ice house keeps alive the pre-refrigeration practice of cutting large blocks of natural pond ice during winter and storing them under insulating sawdust. Special events still demonstrate traditional ice harvesting using old tools and techniques.', 'limited', 'https://www.atlasobscura.com/places/the-thompson-ice-house-harvesting-museum-south-bristol-maine', null, 'America/New_York', now()),
  ('Grave of Sarah Ware', 'grave-of-sarah-ware', 'weird-history', 44.57505, -68.79688, 'Bucksport', 'ME', 'Sarah Ware was murdered in 1898 in a case that remains one of Bucksport’s enduring unsolved crimes. Her severed head was reportedly retained as evidence for decades before eventually being returned for burial near her cemetery marker.', 'open', 'https://www.atlasobscura.com/places/grave-sarah-ware', null, 'America/New_York', now()),
  ('Alexander Art Trail', 'alexander-art-trail', 'roadside-oddities', 45.056, -67.4956, 'Alexander', 'ME', 'More than two dozen large hand-carved wooden sculptures line a trail through the woods in rural Washington County. The privately created but visitor-friendly outdoor collection includes human figures, animals, and imaginative forms carved primarily from local trees.', 'open', 'https://www.atlasobscura.com/places/alexander-art-trail', null, 'America/New_York', now()),
  ('Bailey Island Bridge — Cribstone Bridge', 'bailey-island-bridge-cribstone-bridge', 'roadside-oddities', 43.7489, -69.98893, 'Harpswell', 'ME', 'This unusual bridge is built from massive granite blocks stacked in an open crib-like pattern instead of a conventional solid foundation. Gaps between the stones allow tides to flow through while the heavy granite keeps the structure anchored between Bailey and Orr’s islands.', 'open', 'https://www.atlasobscura.com/places/bailey-island-bridge-cribstone-bridge', null, 'America/New_York', now()),
  ('D.T. Sheridan Shipwreck', 'dt-sheridan-shipwreck', 'weird-history', 43.75594, -69.30842, 'Monhegan', 'ME', 'The rusted remains of the tugboat D.T. Sheridan lie along the rocky shoreline of Monhegan Island after the vessel wrecked there in 1948. Reaching the site requires a ferry to the island followed by a hike, and visitors should stay well clear of dangerous surf.', 'limited', 'https://www.atlasobscura.com/places/d-t-sheridan-shipwreck', null, 'America/New_York', now()),
  ('Chamberlain Freedom Park', 'chamberlain-freedom-park', 'weird-history', 44.79773, -68.76144, 'Brewer', 'ME', 'This small park commemorates Maine’s connection to the Underground Railroad and includes a striking sculpture of a person emerging from a tunnel toward freedom. It stands near the former home of abolitionist John Holyoke and represents a side of Bangor-area history that is easy to overlook.', 'open', 'https://www.atlasobscura.com/places/chamberlain-freedom-park', null, 'America/New_York', now()),
  ('Small Town X Fisherman Statue', 'small-town-x-fisherman-statue', 'roadside-oddities', 44.90444, -66.98442, 'Eastport', 'ME', 'This oversized fiberglass fisherman was created during production of the reality series Murder in Small Town X, which filmed in Eastport. The statue later took on a more serious meaning as a memorial to the show’s winner, New York firefighter Ángel Juarbe Jr., who died on September 11, 2001.', 'open', 'https://www.atlasobscura.com/places/small-town-x-fisherman-statue', null, 'America/New_York', now()),
  ('Katahdin Iron Works', 'katahdin-iron-works', 'weird-history', 45.41601, -69.07226, 'Katahdin Iron Works Township', 'ME', 'A surviving blast furnace and charcoal kiln mark the remains of a remote ironmaking settlement that operated in the Maine woods during the 1800s. Access uses private-resource roads shared with logging traffic and may involve checkpoint fees and seasonal conditions.', 'limited', 'https://www.atlasobscura.com/places/katahdin-iron-works', null, 'America/New_York', now()),
  ('Pushcart Press — Tiny Roadside Bookstore', 'pushcart-press-tiny-roadside-bookstore', 'roadside-oddities', 44.323, -68.63839, 'Sedgwick', 'ME', 'A tiny self-service roadside bookshop associated with Pushcart Press claims the title of the world’s smallest bookstore. The roughly shed-sized structure uses an honor-system setup and looks more like a miniature book stand than a conventional store.', 'roadside', 'https://www.atlasobscura.com/places/pushcart-press-maine', null, 'America/New_York', now()),
  ('Hannibal Hamlin’s Death Couch', 'hannibal-hamlins-death-couch', 'weird-history', 44.80443, -68.77158, 'Bangor', 'ME', 'Bangor Public Library displays the couch on which Hannibal Hamlin, Abraham Lincoln’s first vice president, died in 1891. Rather than being hidden away in storage, the piece of furniture survives as an unusually direct artifact from a former vice president’s final moments.', 'limited', 'https://www.atlasobscura.com/places/hannibal-hamlin-death-couch', null, 'America/New_York', now()),
  ('Million Dollar Birdhouse Wall', 'million-dollar-birdhouse-wall', 'roadside-oddities', 45.14011, -69.94844, 'Moscow', 'ME', 'More than a hundred imaginative birdhouses line a long roadside display north of Moscow. They are constructed in an array of shapes and materials, turning an otherwise remote stretch of U.S. Route 201 into an unexpectedly elaborate folk-art installation.', 'roadside', 'https://www.atlasobscura.com/places/roadside-birdhouses-of-moscow-maine', null, 'America/New_York', now()),
  ('South Solon Meeting House', 'south-solon-meeting-house', 'roadside-oddities', 44.91311, -69.77861, 'Solon', 'ME', 'The plain exterior of this early-1800s meeting house hides an interior almost completely covered in vivid frescoes painted by artists in the 1950s. Biblical, symbolic, and surreal imagery fills walls and ceilings, creating one of Maine’s most unexpected historic interiors.', 'limited', 'https://www.atlasobscura.com/places/south-solon-meeting-house', null, 'America/New_York', now()),
  ('The Sewer Drain That Inspired “IT”', 'the-sewer-drain-that-inspired-it', 'roadside-oddities', 44.80512, -68.78521, 'Bangor', 'ME', 'A storm drain at the corner of Union and Jackson streets is locally identified as an inspiration for the infamous sewer imagery in Stephen King’s IT. It is an ordinary piece of city infrastructure, so this is a quick public-street stop rather than an attraction to enter or disturb.', 'roadside', 'https://www.atlasobscura.com/places/the-sewer-drain-from-it', null, 'America/New_York', now()),
  ('Temple Heights Spiritual Camp', 'temple-heights-spiritual-camp', 'haunted', 44.34585, -68.95182, 'Northport', 'ME', 'Founded in the 1800s, Temple Heights developed as a Spiritualist camp centered on mediumship, spirit communication, healing, and religious gatherings. The community still hosts scheduled services, readings, and events, making it a living continuation of New England Spiritualism rather than simply a historic site.', 'limited', 'https://www.atlasobscura.com/places/temple-heights-spiritual-camp', null, 'America/New_York', now()),
  ('Double Eagle II Balloon Site', 'double-eagle-ii-balloon-site', 'weird-history', 46.62732, -68.02103, 'Presque Isle', 'ME', 'A small park commemorates the field where Double Eagle II launched in 1978 before completing the first successful transatlantic balloon crossing. Displays and a balloon replica mark the beginning of a flight that ended thousands of miles away in France.', 'open', 'https://www.atlasobscura.com/places/double-eagle-balloon-site', null, 'America/New_York', now()),
  ('Finny — 50-Foot Whale Skeleton', 'finny-50-foot-whale-skeleton', 'museums', 43.83941, -70.12115, 'Freeport', 'ME', 'A roughly 50-foot fin-whale skeleton nicknamed “Finny” hangs overhead inside Maine Beer Company’s Freeport facility. The enormous specimen turns a commercial stop into an unexpected natural-history display and was installed after the whale’s remains were recovered and prepared for exhibition.', 'open', 'https://www.atlasobscura.com/places/maine-beer-company', null, 'America/New_York', now()),
  ('“Pinecone” — Giant Shovel Sculpture', 'pinecone-giant-shovel-sculpture', 'roadside-oddities', 43.65884, -70.27189, 'Portland', 'ME', 'An eight-foot steel pine cone stands in Deering Oaks Park, but its overlapping scales are actually made from roughly 140 recycled shovel heads. The transformation is obvious only when viewed closely, making the sculpture a good quick OddWay reveal.', 'open', 'https://www.atlasobscura.com/places/pinecone', null, 'America/New_York', now()),
  ('Museum of Beadwork', 'museum-of-beadwork', 'museums', 43.67906, -70.28788, 'Portland', 'ME', 'This specialized museum focuses entirely on beadwork as art, craft, and cultural expression. Exhibitions range from contemporary pieces to traditions from different communities, creating a museum around a material that is usually relegated to a small section elsewhere.', 'limited', 'https://www.atlasobscura.com/places/museum-of-beadwork', null, 'America/New_York', now()),
  ('Seal Cove Auto Museum', 'seal-cove-auto-museum', 'museums', 44.30542, -68.40422, 'Tremont', 'ME', 'This Mount Desert Island museum concentrates on automobiles and motorcycles from the earliest decades of motoring, including exceptionally old and unusual vehicles. Period accessories and devices help show just how experimental road travel looked before modern cars became standardized.', 'limited', 'https://www.atlasobscura.com/places/seal-cove-auto-museum', 'https://www.sealcoveautomuseum.org/', 'America/New_York', now()),
  ('Bath–Tsugaru Sister City Torii Gate', 'bath-tsugaru-sister-city-torii-gate', 'roadside-oddities', 43.91147, -69.81239, 'Bath', 'ME', 'An authentic Japanese torii gate stands unexpectedly on Bath’s waterfront as a symbol of the city’s relationship with Tsugaru, Japan. The connection grew from the 1889 rescue of shipwrecked American sailors from a Bath-built vessel off the Japanese coast.', 'open', 'https://www.atlasobscura.com/places/bath-tsugaru-sister-city-torii-gate', null, 'America/New_York', now()),
  ('Fort McClary State Historic Site', 'fort-mcclary-state-historic-site', 'roadside-oddities', 43.08244, -70.71037, 'Kittery', 'ME', 'Fortifications have guarded this bluff above the Piscataqua River for centuries, although the site saw remarkably little actual combat. Surviving earthworks, granite structures, and the distinctive blockhouse create a layered military ruin spanning multiple periods of American history.', 'limited', 'https://www.atlasobscura.com/places/fort-mcclary-state-historic-site', null, 'America/New_York', now()),
  ('Samantha Smith — America’s Little Ambassador Statue', 'samantha-smith-americas-little-ambassador-statue', 'weird-history', 44.30591, -69.78281, 'Augusta', 'ME', 'A bronze statue outside the Maine State Museum honors Samantha Smith, the Maine schoolgirl who wrote to Soviet leader Yuri Andropov in 1982 asking why the Soviet Union wanted war. Her letter led to an invitation to visit the USSR, turning her into an unlikely child peace ambassador before her death in a 1985 plane crash. The sculpture shows Samantha releasing a dove while a bear cub sits beside her.', 'open', 'https://www.roadsideamerica.com/tip/22890', null, 'America/New_York', now()),
  ('Cole Land Transportation Museum', 'cole-land-transportation-museum', 'museums', 44.78517, -68.80457, 'Bangor', 'ME', 'This large transportation museum preserves an eclectic collection of Maine road, rail, military, farm, and commercial vehicles. Exhibits range from snowplows and fire engines to motorcycles, trains, military equipment, and historic machinery, making it much broader and stranger than a conventional car museum.', 'limited', 'https://fotospot.com/attractions/maine/cole-land-transportation-museum', 'https://www.colemuseum.org/', 'America/New_York', now()),
  ('Pink Floyd — Pink Dinosaur Skeleton', 'pink-floyd-pink-dinosaur-skeleton', 'roadside-oddities', 44.43345, -68.9982, 'Belfast', 'ME', 'Beside Perry’s Nut House stands a bright pink metal dinosaur skeleton known as Pink Floyd. The current version was built by Skowhegan High School students as a sturdier replacement for an earlier wooden dinosaur, continuing the site’s long tradition of bizarre roadside displays.', 'roadside', 'https://www.roadsideamerica.com/tip/10583', null, 'America/New_York', now()),
  ('Hawthorne II — Rooftop Elephant', 'hawthorne-ii-rooftop-elephant', 'roadside-oddities', 44.42649, -69.00779, 'Belfast', 'ME', 'A life-size elephant named Hawthorne II has stood above the Colonial Theatre since 1997, staring down over downtown Belfast from the roof and marquee area. The elephant originally came from Perry’s Nut House and became one of the theater’s most recognizable eccentric features.', 'roadside', 'https://www.roadsideamerica.com/tip/49944', 'https://colonialtheatre.com/about/', 'America/New_York', now()),
  ('Androscoggin Swinging Bridge', 'androscoggin-swinging-bridge', 'roadside-oddities', 43.91729, -69.97244, 'Brunswick', 'ME', 'Built in 1892 by John A. Roebling’s Sons, the company associated with the Brooklyn Bridge, this pedestrian suspension bridge crosses the Androscoggin River between Brunswick and Topsham. Locals call it the Swinging Bridge because the narrow span noticeably moves beneath walkers.', 'open', 'https://www.androscogginriverwalk.org/riverwalk-photo-tour.html', null, 'America/New_York', now()),
  ('Pet Sematary Creed House', 'pet-sematary-creed-house', 'weird-history', 44.50839, -68.25468, 'Hancock', 'ME', 'This private home at 303 Point Road served as the exterior of the Creed family house in the 1989 adaptation of Stephen King’s Pet Sematary. The nearby road was also used in scenes connected with the film’s deadly highway, making the location recognizable to horror fans despite being an ordinary residence today. View only from public areas and do not enter the property.', 'private', 'https://www.roadsideamerica.com/tip/40892', null, 'America/New_York', now()),
  ('20-Foot Poseidon Tree Sculpture', '20-foot-poseidon-tree-sculpture', 'roadside-oddities', 44.46542, -68.91053, 'Searsport', 'ME', 'A dead roadside tree outside the Yardarm Motel was transformed in 2025 into an approximately 20-foot carving of Poseidon by artist Josh Landry. The sea god rises from the trunk holding a trident, creating a particularly fitting giant figure along Maine’s coast.', 'roadside', 'https://www.roadsideamerica.com/tip/89762', null, 'America/New_York', now()),
  ('Hamlin Memorial Library & Museum — Museum in a Jail', 'hamlin-memorial-library-museum-museum-in-a-jail', 'museums', 44.26011, -70.50221, 'South Paris', 'ME', 'This local library and museum occupies Oxford County’s former stone jail, giving visitors a chance to see historic cells alongside collections tied to the area and the Hamlin family. The unusual reuse leaves much of the old lockup atmosphere intact instead of disguising the building’s original purpose.', 'limited', 'https://www.hamlin.lib.me.us/contact_us.html', null, 'America/New_York', now()),
  ('Maiden Cliff Cross', 'maiden-cliff-cross', 'weird-history', 44.25528, -69.09338, 'Camden', 'ME', 'A large white cross stands high above Megunticook Lake at Maiden Cliff. It memorializes 12-year-old Elenora French, who died in 1864 after being swept from the cliff while visiting the area. The cross is reached by trail and has become a stark landmark above the lake.', 'limited', 'https://www.visitmaine.com/article/maiden-cliff-trail/', null, 'America/New_York', now()),
  ('Snowshoe Rock of Doom', 'snowshoe-rock-of-doom', 'folklore', 43.16937, -70.66381, 'York Harbor', 'ME', 'A plaque on a roadside boulder marks a local story connected to the Candlemas Massacre of 1692 and a pair of abandoned snowshoes said to have warned settlers of danger. The modern marker has an added OddWay twist: accounts say it was deliberately placed on a different rock so visitors would not trespass at the actual traditional site.', 'roadside', 'https://www.roadsideamerica.com/story/64305', null, 'America/New_York', now()),
  ('Pocomoonshine Lake — Serpent Legend', 'pocomoonshine-lake-serpent-legend', 'cryptids', 45.14628, -67.51144, 'Princeton', 'ME', 'Pocomoonshine Lake is tied to one of Maine’s lesser-known lake-monster traditions. Stories recorded in the region describe a huge serpent-like creature and strange trails supposedly left as it crossed between bodies of water. The coordinates lead to a legitimate public boat-launch access point, not to a claimed encounter location.', 'open', 'https://folkbestiary.com/maine/', null, 'America/New_York', now()),
  ('Owls Head Lighthouse', 'owls-head-lighthouse', 'haunted', 44.09224, -69.04408, 'Owls Head', 'ME', 'Perched above Penobscot Bay, Owls Head Light combines dramatic coastal scenery with a collection of long-running ghost and maritime legends. Stories associated with the site include unexplained footsteps and apparitions as well as tales of the lighthouse keeper’s dog Spot, who famously rang a bell to warn passing vessels. Paranormal claims remain folklore.', 'limited', 'https://lighthousefoundation.org/lighthouses/owls-head-light/', null, 'America/New_York', now()),
  ('Pemaquid Point Lighthouse', 'pemaquid-point-lighthouse', 'haunted', 43.83698, -69.50602, 'Bristol', 'ME', 'One of Maine’s most recognizable lighthouses also carries a local ghost tradition involving the apparition of a woman sometimes described as wearing a red shawl. The tower and surrounding rocky point are real public attractions; the haunting is regional folklore rather than a verified event.', 'limited', 'https://lighthousefoundation.org/lighthouses/pemaquid-point-light/', null, 'America/New_York', now()),
  ('Wood Island Lighthouse', 'wood-island-lighthouse', 'haunted', 43.45679, -70.32898, 'Biddeford Pool', 'ME', 'Wood Island Light stands offshore from Biddeford Pool and has accumulated stories of unexplained voices, footsteps, and other activity tied to the island’s difficult past. The lighthouse is not connected to the mainland by road, so closer visits depend on seasonal boat access and tour availability.', 'limited', 'https://lighthousefoundation.org/lighthouses/wood-island-light/', null, 'America/New_York', now()),
  ('Eastern Cemetery', 'eastern-cemetery', 'weird-history', 43.66252, -70.25009, 'Portland', 'ME', 'Portland’s oldest historic cemetery contains markers dating to the early 1700s, underground tombs, maritime graves, and the burial places of captains connected with the War of 1812 battle between the Enterprise and Boxer. Seasonal guided tours reveal stories and structures that are easy to miss from the street.', 'limited', 'https://www.visitportland.com/event/spirits-alive-walking-tours/', null, 'America/New_York', now()),
  ('Fort William Henry at Colonial Pemaquid', 'fort-william-henry-at-colonial-pemaquid', 'weird-history', 43.87724, -69.52334, 'Bristol', 'ME', 'A reconstructed stone tower rises over the archaeological remains of Colonial Pemaquid, where multiple forts and settlements were repeatedly built, attacked, destroyed, and rebuilt along Maine’s contested early frontier. The current structure recreates part of the 1690s Fort William Henry and overlooks the harbor and excavation grounds.', 'limited', 'https://www.maine.gov/dacf/parks/contact.shtml', null, 'America/New_York', now()),
  ('Timber Tina’s Great Maine Lumberjack Show', 'timber-tinas-great-maine-lumberjack-show', 'museums', 44.50267, -68.38465, 'Trenton', 'ME', 'Timber Tina’s outdoor show turns traditional lumberjack skills into a competitive performance featuring axe throwing, log rolling, chopping, sawing, and other old logging-camp techniques. It has the feel of a surviving piece of exaggerated North Woods culture performed live rather than preserved behind museum glass.', 'limited', 'https://mainelumberjack.com/', null, 'America/New_York', now()),
  ('Stanley Museum', 'stanley-museum', 'museums', 44.95536, -70.1553, 'Kingfield', 'ME', 'The Stanley family produced far more than the famous Stanley Steamer automobile. This museum explores their steam cars alongside photography, early airbrush technology, violins, and other inventions connected to a remarkably inventive Maine family.', 'limited', 'https://stanleymuseum.org/', null, 'America/New_York', now()),
  ('Damariscotta Mills Historic Fish Ladder', 'damariscotta-mills-historic-fish-ladder', 'roadside-oddities', 44.06194, -69.52656, 'Newcastle', 'ME', 'A historic stone fish ladder climbs from the Damariscotta River system toward Damariscotta Lake, allowing enormous runs of alewives to bypass the old mill site. During the spring migration, thousands of fish can crowd the narrow channel at once, turning a piece of practical infrastructure into a strange natural spectacle.', 'open', 'https://www.newenglandswimmingholes.com/maine/waterfalls/damariscotta-mills', null, 'America/New_York', now()),
  ('Boy and the Boot Fountain', 'boy-and-the-boot-fountain', 'roadside-oddities', 46.125, -67.83028, 'Houlton', 'ME', 'A statue of a boy holding a leaking boot has stood in Houlton for more than a century as one of many versions of the once-popular “Boy and the Boot” fountain design. The Houlton figure is traditionally removed or protected during the harshest part of winter, so visibility can be seasonal.', 'limited', 'https://www.roadsideamerica.com/story/7825', null, 'America/New_York', now()),
  ('Grave of the Unknown Confederate Stranger', 'grave-of-the-unknown-confederate-stranger', 'weird-history', 43.88533, -70.33277, 'Gray', 'ME', 'A Confederate soldier whose identity remains unknown is buried in Gray after his body was mistakenly shipped north during the Civil War in place of Union soldier Charles Colley. Unable to determine who the stranger was or where to return him, local residents buried him in Maine, leaving one of the state’s strangest Civil War graves.', 'open', 'https://www.bangordailynews.com/2020/06/26/news/state-news/how-7-confederate-soldiers-came-to-be-buried-in-maine/', null, 'America/New_York', now()),
  ('Fort Edgecomb', 'fort-edgecomb', 'roadside-oddities', 43.99361, -69.65722, 'Edgecomb', 'ME', 'Built in 1808–09 to defend the busy port of Wiscasset, Fort Edgecomb is dominated by an unusual two-story octagonal wooden blockhouse. The rare structure survives as a state historic site overlooking the Sheepscot River and is among Maine’s most distinctive early coastal defenses.', 'limited', 'https://www.maine.gov/mhpc/index.php/did-you-know/fort-edgecomb-c1808-edgecomb-lincoln-county', 'https://www.maine.gov/fortedgecomb', 'America/New_York', now()),
  ('Only Octagonal Post Office', 'only-octagonal-post-office', 'roadside-oddities', 44.39194, -69.30722, 'Liberty', 'ME', 'This tiny eight-sided building began as a harness shop in 1870 and later served as Liberty’s post office. The town promotes it as the only octagonal post-office building in the United States; it now operates as a small historical museum with limited summer access.', 'limited', 'https://www.roadsideamerica.com/tip/58804', null, 'America/New_York', now()),
  ('Big Easy Chair', 'big-easy-chair', 'roadside-oddities', 43.08693, -70.75096, 'Kittery', 'ME', 'A roughly 12-foot-tall easy chair with a fiberglass shell sits beside Government Street in Kittery. Vandals destroyed the original oversized chair in 2011, but the community rebuilt it the following year, preserving one of southern Maine’s simplest and most photogenic giant-object stops.', 'roadside', 'https://fotospot.com/attractions/maine/big-easy-chair', null, 'America/New_York', now()),
  ('Sylvia Hardy — Life-Size Maine Giantess', 'sylvia-hardy-life-size-maine-giantess', 'museums', 44.58617, -70.23395, 'Wilton', 'ME', 'The Wilton Farm and Home Museum displays a life-size figure of Sylvia Hardy, a Maine woman who stood more than seven and a half feet tall and later toured with P.T. Barnum’s shows. The exhibit includes one of Hardy’s actual dresses, making her extraordinary height much easier to comprehend.', 'limited', 'https://www.roadsideamerica.com/tip/36288', null, 'America/New_York', now()),
  ('Muhammad Ali Statue', 'muhammad-ali-statue', 'weird-history', 44.0979, -70.2203, 'Lewiston', 'ME', 'A 10-foot bronze Muhammad Ali was unveiled in 2025 near Bates Mill No. 5 to mark 60 years since Ali’s bizarrely brief 1965 rematch with Sonny Liston in Lewiston. The fight ended in the first round after the controversial “phantom punch,” creating one of the strangest heavyweight-title moments in boxing history.', 'open', 'https://www.roadsideamerica.com/tip/87760', null, 'America/New_York', now()),
  ('John Ford Statue', 'john-ford-statue', 'weird-history', 43.65448, -70.25734, 'Portland', 'ME', 'Portland honors legendary director John Ford with a bronze statue showing him seated in a director’s chair with his trademark hat and pipe. Stones surrounding the sculpture recognize the films that earned Ford Academy Awards, linking an ordinary downtown corner to one of Hollywood’s most influential filmmakers.', 'open', 'https://www.atlasobscura.com/places/john-ford-statue', 'https://www.publicartportland.org/project/the-john-ford-statue/', 'America/New_York', now()),
  ('Maine Lobsterman Statue', 'maine-lobsterman-statue', 'weird-history', 43.65752, -70.25582, 'Portland', 'ME', 'This bronze lobsterman traces its origin to a plaster sculpture commissioned for Maine’s display at the 1939 New York World’s Fair. The Portland version depicts a working fisherman kneeling over a lobster, turning a piece of World’s Fair history into a permanent monument to Maine’s best-known industry.', 'open', 'https://www.atlasobscura.com/places/maine-lobsterman-statue', 'https://www.publicartportland.org/project/maine-lobsterman/', 'America/New_York', now()),
  ('World’s Largest Non-Stick Frying Pan', 'worlds-largest-non-stick-frying-pan', 'roadside-oddities', 44.7792, -69.37758, 'Pittsfield', 'ME', 'Pittsfield owns a roughly 10-foot-wide non-stick frying pan associated with the Central Maine Egg Festival. Unlike a permanent roadside giant, the pan is normally kept in storage and brought to Manson Park around festival time, so this stop should be treated as an event-dependent OddWay location.', 'limited', 'https://www.roadsideamerica.com/tip/10801', null, 'America/New_York', now()),
  ('Madawaska Four Corners Park — Long-Distance Biker Shrine', 'madawaska-four-corners-park-long-distance-biker-shrine', 'roadside-oddities', 47.35596, -68.33242, 'Madawaska', 'ME', 'This unusual park marks the northeastern corner of a four-corners touring tradition for long-distance motorcyclists crossing the continental United States. Monuments, engraved pavers, and rider records commemorate travelers who complete enormous cross-country circuits linking Madawaska with the other recognized corners.', 'open', 'https://www.roadsideamerica.com/tip/29863', 'https://madawaskafourcorners.org/', 'America/New_York', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as maine from public.stops where state = 'ME';
